            gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
            GSLVector._lib = gsl

        self._vector = GSLVector._lib.gsl_vector_double_alloc(len(values))
        for i in range(len(values)):
            GSLVector._lib.gsl_vector_double_set(self._vector, i, values[i])

    def __del__(self):
        GSLVector._lib.gsl_vector_double_free(self._vector)

    def get_values(self):
        result = [0.0] * self._vector.size
        for i in range(self._vector.size):
            result[i] = GSLVector._lib.gsl_vector_double_get(self._vector, i)
        return result


