        self.rows = rows
        self.cols = cols
        self._allocate()

    def _allocate(self):
        self.data = (ctypes.c_double * (self.rows * self.cols))()

    def free(self):
        self.data = None

    def to_numpy(self):
        return np.array([self.data[i*self.cols:(i+1)*self.cols] for i in range(self.rows)], dtype=np.float64)

