def compute_inverse_hyperbolic_functions(x):
    if x < 1:
        return (float("nan"), float("nan"), float("nan"))
    if x > 1:
        return (float("nan"), float("nan"), float("nan"))

    acosh = gsl.gsl_acosh
    acosh.argtypes = [ctypes.c_double]
    acosh.restype = ctypes.c_double

    asinh = gsl.gsl_asinh
    asinh.argtypes = [ctypes.c_double]
    asinh.restype = ctypes.c_double

    atanh = gsl.gsl_atanh
    atanh.arg-than = [ctypes.c_double]
    atanh.restype = ctypes.c_double

    return (acosh(x), asinh(x), atanh(x))

