import numpy as np

class GslSfResult(ctypes.Structure):
    _fields_ = [
        ('sign', ctypes.c_int),
        ('error', ctypes.c_double)
    ]

def compute_mathieu_mc(kind, order, qq, zz):
    if not (kind in (1, 2)):
        raise ValueError("kind must be 1 or 2")
    if qq <= 0:
        raise ValueError("qq must be greater than 0")

    # Load required libraries
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except Exception as e:
        raise RuntimeError("Failed to load GSL libraries: "+str(e))

    # Define function signature
    gsl_sf_mathieu_Mc_e = gsl.gsl_sf_mathieu_Mc_e
    gsl_sf_mathieu_Mc_e.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.c_double, ctypes.c_double, ctypes.POINTER(GslSfResult)]
    gsl_sf_mathieu_Mc_e.restype = ctypes.c_int

    result = GslSfResult()

    # Call the C function
    status = gsl_sf_mathieu_Mc_e(kind, order, qq, zz, ctypes.byref(result))

    if status != 0:
        raise RuntimeError("GSL function failed with status: "+str(status))

    return (np.sign(result.sign) * np.cos(zz), result.error)

