def compute_clausen(x):
    """Compute the Clausen function value for a given input x."""
    if not isinstance(x, (int, float)):
        raise ValueError("Input must be a float or integer")

    # Convert x to a double
    x_double = ctypes.c_double(x)

    # Call the GSL function
    try:
        result = gsl.sf_clausen(x_double.value)
    except Exception as e:
